function uploadImages(int $id): array {
    getProduct($id,true);if(!extension_loaded('gd'))fail('PHP GD is required for image processing.',503);$f=$_FILES['images']??null;if(!$f)fail('Choose at least one photo.');$names=is_array($f['name'])?$f['name']:[$f['name']];if(count($names)>8)fail('Upload at most eight photos.');$dir=ROOT.'/public/uploads/products';if(!is_dir($dir))mkdir($dir,0755,true);$sort=(int)(one('SELECT MAX(sort) AS n FROM product_images WHERE product_id=?',[$id])['n']??-1)+1;
    foreach($names as $i=>$name){$tmp=is_array($f['tmp_name'])?$f['tmp_name'][$i]:$f['tmp_name'];$size=is_array($f['size'])?$f['size'][$i]:$f['size'];$err=is_array($f['error'])?$f['error'][$i]:$f['error'];if($err!==UPLOAD_ERR_OK||$size>12*1024*1024)fail('Each photo must be smaller than 12 MB.');$info=@getimagesize($tmp);if(!$info||!in_array($info['mime'],['image/jpeg','image/png','image/webp','image/gif'],true)||$info[0]*$info[1]>40000000)fail('Choose a JPG, PNG, WebP or GIF of at most 40 megapixels.');$src=@imagecreatefromstring(file_get_contents($tmp));if(!$src)fail('The image could not be decoded.');
        if($info['mime']==='image/jpeg'&&function_exists('exif_read_data')){
            $metadata=@exif_read_data($tmp);$orientation=(int)($metadata['Orientation']??1);
            $angle=match($orientation){3=>180,5,6=>-90,7,8=>90,default=>0};
            if($angle){$rotated=imagerotate($src,$angle,0);if($rotated){imagedestroy($src);$src=$rotated;}}
            if(in_array($orientation,[2,5,7],true))imageflip($src,IMG_FLIP_HORIZONTAL);
            if($orientation===4)imageflip($src,IMG_FLIP_VERTICAL);
        }
        $canvas=imagecreatetruecolor(1200,1200);$white=imagecolorallocate($canvas,255,255,255);imagefill($canvas,0,0,$white);$w=imagesx($src);$h=imagesy($src);
        // Preserve the full subject; busy backgrounds receive a blurred square fill.
        $light=0;foreach([[0,0],[$w-1,0],[0,$h-1],[$w-1,$h-1]] as [$x,$y]){$rgb=imagecolorsforindex($src,imagecolorat($src,$x,$y));if(min($rgb['red'],$rgb['green'],$rgb['blue'])>230)$light++;}
        if($light<3){$scale=max(1200/$w,1200/$h);imagecopyresampled($canvas,$src,(int)((1200-$w*$scale)/2),(int)((1200-$h*$scale)/2),0,0,(int)($w*$scale),(int)($h*$scale),$w,$h);for($j=0;$j<10;$j++)imagefilter($canvas,IMG_FILTER_GAUSSIAN_BLUR);}
        $scale=min(1120/$w,1120/$h);imagecopyresampled($canvas,$src,(int)((1200-$w*$scale)/2),(int)((1200-$h*$scale)/2),0,0,(int)($w*$scale),(int)($h*$scale),$w,$h);
        $markPath=ROOT.'/public/brand/matte-m.png';if(!is_file($markPath))fail('Brand watermark is missing.',503);$mark=imagecreatefrompng($markPath);$mw=150;$mh=(int)($mw*imagesy($mark)/imagesx($mark));imagecopyresampled($canvas,$mark,1020,1200-$mh-30,0,0,$mw,$mh,imagesx($mark),imagesy($mark));
        $base='product-'.$id.'-'.bin2hex(random_bytes(8));if(!imagejpeg($canvas,$dir.'/'.$base.'.jpg',88))throw new RuntimeException('Could not save product photo.');$thumb=imagescale($canvas,360,360);imagejpeg($thumb,$dir.'/'.$base.'-sm.jpg',85);insert('product_images',['product_id'=>$id,'base_name'=>$base,'sort'=>$sort++]);imagedestroy($src);imagedestroy($mark);imagedestroy($canvas);imagedestroy($thumb);
    }return getProduct($id,true);
}
function invoiceHtml(array $o): string {
    $site=siteContent();$c=$site['business'];$money=fn($n)=>$o['currency']==='USD'?number_format($n/(float)$o['usd_rwf_rate'],2):number_format($n);$date=(new DateTimeImmutable($o['created_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Africa/Kigali'))->format('d/m/Y');
    $img=fn($name)=>'data:'.(str_ends_with($name,'.png')?'image/png':'image/jpeg').';base64,'.base64_encode(file_get_contents(ROOT.'/public/brand/'.$name));
    $html='<html><head><meta charset="UTF-8"><style>@page{margin:42px 50px}body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#111}h1{text-align:center;font-size:19px}table{width:100%;border-collapse:collapse}td,th{padding:7px;vertical-align:top}thead{display:table-header-group}.lines td,.lines th{border:1px solid #111}.lines tr{page-break-inside:avoid}.right{text-align:right}.brand{border-bottom:4px double #111}.stamp{page-break-inside:avoid;padding:20px;text-align:center}.small{font-size:9px}footer{position:fixed;bottom:-20px;text-align:center;width:100%}</style></head><body><table class="brand"><tr><td><img width="130" src="'.$img('logo.png').'"></td><td><b>'.e($c['name']).'</b><br>'.e($c['receiptPlace']).'<br>TIN: '.e($c['tin']).'<br>TEL: '.e($c['tel']).'<br>E-mail: '.e($c['email']).'</td></tr></table><table><tr><td>Proforma No.: '.e($o['proforma_no']).'</td><td class="right">Date: '.$date.'</td></tr></table><h1>PROFORMA INVOICE</h1><p><b>Client Names: '.e($o['customer_name'].' '.($o['customer_company']??'')).'</b><br>'.($o['customer_tin']?'TIN: '.e($o['customer_tin']).' | Purchase code: '.e($o['purchase_code']):'TEL: '.e($o['customer_phone'])).'<br>'.($o['delivery_method']==='delivery'?'Delivery: '.e($o['delivery_address']):'Pick-up at store').'</p><table class="lines"><thead><tr><th>No</th><th>Description</th><th>Quantity</th><th>Unit Price</th><th>Total Price</th></tr></thead><tbody>';
    foreach(orderItems((int)$o['id']) as $i=>$line)$html.='<tr><td>'.($i+1).'</td><td>'.e($line['description']).'</td><td>'.$line['qty'].'</td><td class="right">'.$money($line['unit_price_rwf']).'</td><td class="right">'.$money($line['line_total_rwf']).'</td></tr>';
    $html.='<tr><td colspan="4"><b>TOTAL ('.e($o['currency']).')</b></td><td class="right"><b>'.$money($o['total_rwf']).'</b></td></tr></tbody></table>';
    if($o['note'])$html.='<p>Notes: '.nl2br(e($o['note'])).'</p>';if($o['service_request']!=='none')$html.='<p>Installation: '.e($o['service_request'].' '.($o['service_note']??'')).'</p>';
    return $html.'<div class="stamp"><p style="margin:0 0 18px"><b>STAMP &amp; SIGNATURE</b></p><table style="width:260px;margin:0 auto"><tr><td style="width:130px"><img style="display:block" width="120" src="'.$img('matte-stamp.jpeg').'"></td><td style="width:110px"><img style="display:block" width="100" src="'.$img('matte-signature.png').'"></td></tr></table></div><p class="small">'.e($c['paymentInstructions']).'</p><footer>Thank you for your business - '.e($c['name']).'</footer></body></html>';
}
function pdfBytes(array $o): string {if(!$o['invoice_requested'])fail('This order does not have an invoice.',404);if(!class_exists(Dompdf\Dompdf::class))fail('Install Composer dependencies to generate PDFs.',503);$options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('chroot',ROOT.'/public');$options->set('tempDir',ROOT.'/storage');$options->set('fontCache',ROOT.'/storage');$pdf=new Dompdf\Dompdf($options);$pdf->loadHtml(invoiceHtml($o),'UTF-8');$pdf->setPaper('letter');$pdf->render();return $pdf->output();}
function processMail(): void {
    if(env('MAIL_WORKER_ENABLED','false')!=='true'||!env('SMTP_HOST')||!class_exists(PHPMailer\PHPMailer\PHPMailer::class))return;
    foreach(rows('SELECT id FROM mail_jobs WHERE sent_at IS NULL AND available_at<=NOW() ORDER BY id LIMIT 10') as $candidate){$job=tx(function()use($candidate){$r=one('SELECT * FROM mail_jobs WHERE id=? AND sent_at IS NULL AND available_at<=NOW() FOR UPDATE',[$candidate['id']]);if($r)sql('UPDATE mail_jobs SET attempts=attempts+1,available_at=DATE_ADD(NOW(),INTERVAL 10 MINUTE) WHERE id=?',[$r['id']]);return $r;});if(!$job)continue;
        try{$o=one('SELECT * FROM orders WHERE id=?',[$job['order_id']]);$mail=new PHPMailer\PHPMailer\PHPMailer(true);$mail->isSMTP();$mail->Host=env('SMTP_HOST');$mail->Port=(int)env('SMTP_PORT','587');$mail->SMTPAuth=(bool)env('SMTP_USER');$mail->Username=env('SMTP_USER');$mail->Password=env('SMTP_PASS');$mail->SMTPSecure=$mail->Port===465?'ssl':'tls';$mail->CharSet='UTF-8';$mail->setFrom(env('MAIL_FROM',env('SMTP_USER')),'MATTE LTD');$mail->addAddress($o['customer_email'],$o['customer_name']);$url=rtrim(env('APP_URL'),'/').'/order/'.$o['public_token'];$mail->Subject=$job['kind']==='proforma'?'MATTE proforma '.$o['proforma_no']:'Your MATTE order has been delivered';$mail->Body='Hello '.$o['customer_name'].",\n\n".($job['kind']==='proforma'?'Your proforma is attached.':'Your order has been delivered.')."\nView your order: ".$url;
            if($job['kind']==='proforma')$mail->addStringAttachment(pdfBytes($o),'Proforma-'.$o['proforma_no'].'.pdf','base64','application/pdf');$mail->send();tx(function()use($job,$o){sql('UPDATE mail_jobs SET sent_at=NOW() WHERE id=?',[$job['id']]);if($job['kind']==='delivery')sql('UPDATE orders SET delivery_notified_at=NOW() WHERE id=? AND delivery_notified_at IS NULL',[$o['id']]);});
        }catch(Throwable $e){error_log('MATTE email job '.$job['id'].' failed; retained for retry.');}
    }
}
